	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		PaymentOrder
	 */
		public PaymentOrder createPaymentOrder( CreatePaymentOrderCommand command ) {

		PaymentOrder entity = new PaymentOrder();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setPaymentOrderId( command.getPaymentOrderId() );
            entity.setOrderReference( command.getOrderReference() );
            entity.setRequestedExecutionDate( command.getRequestedExecutionDate() );
            entity.setPurpose( command.getPurpose() );
            entity.setPaymentMethod( command.getPaymentMethod() );
            entity.setStatus( command.getStatus() );
            entity.setPriority( command.getPriority() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of PaymentOrder {0} ", entity.toString() );

		return entity;
	}

